-- Lot du 18/11/2026 : photos Promotion de la santé et Don en nature, trois logos de partenaires, signature Nomad Impact.
-- Aucune suppression. Les autres contenus saisis dans le CMS ne sont pas touchés.
begin;
insert into public.medias (id, fichier, alt, credit, largeur, hauteur, ordre, publie, type_visuel) values ('m-promotion-sante', 'promotion-sante.png', 'Une soignante en blouse blanche, stéthoscope autour du cou, écoute un homme assis face à elle', '', 1400, 921, 31, true, 'detoure') on conflict (id) do update set fichier = excluded.fichier, alt = excluded.alt, largeur = excluded.largeur, hauteur = excluded.hauteur, type_visuel = excluded.type_visuel;
insert into public.medias (id, fichier, alt, credit, largeur, hauteur, ordre, publie, type_visuel) values ('m-don-nature', 'soutenir-don-nature.png', 'Une femme remet un manteau plié à un homme en bonnet et veste d’hiver', '', 1400, 950, 32, true, 'detoure') on conflict (id) do update set fichier = excluded.fichier, alt = excluded.alt, largeur = excluded.largeur, hauteur = excluded.hauteur, type_visuel = excluded.type_visuel;
insert into public.medias (id, fichier, alt, credit, largeur, hauteur, ordre, publie, type_visuel) values ('m-logo-relais-social', 'logo-relais-social.png', 'Relais Social de Charleroi', '', 186, 189, 33, true, 'photo') on conflict (id) do update set fichier = excluded.fichier, alt = excluded.alt, largeur = excluded.largeur, hauteur = excluded.hauteur, type_visuel = excluded.type_visuel;
insert into public.medias (id, fichier, alt, credit, largeur, hauteur, ordre, publie, type_visuel) values ('m-logo-espace-p', 'logo-espace-p.svg', 'Espace P', '', 41, 51, 34, true, '') on conflict (id) do update set fichier = excluded.fichier, alt = excluded.alt, largeur = excluded.largeur, hauteur = excluded.hauteur, type_visuel = excluded.type_visuel;
insert into public.medias (id, fichier, alt, credit, largeur, hauteur, ordre, publie, type_visuel) values ('m-logo-frb', 'logo-fondation-roi-baudouin.svg', 'Fondation Roi Baudouin', '', 227, 53, 35, true, '') on conflict (id) do update set fichier = excluded.fichier, alt = excluded.alt, largeur = excluded.largeur, hauteur = excluded.hauteur, type_visuel = excluded.type_visuel;
update public.services set photo = 'm-promotion-sante', photo_alt = 'Une soignante en blouse blanche, stéthoscope autour du cou, écoute un homme assis face à elle' where slug = 'promotion-sante';
update public.sections set contenu = contenu || '{"image":"m-don-nature","image_alt":"Une femme remet un manteau plié à un homme en bonnet et veste d’hiver"}'::jsonb where id = 'dn-1';
update public.sections set contenu = jsonb_set(contenu, '{rangs}', (select jsonb_agg(case when r->>'service' = 'promotion-sante' then r || '{"image":"m-promotion-sante","image_alt":"Une soignante en blouse blanche, stéthoscope autour du cou, écoute un homme assis face à elle"}'::jsonb else r end order by o) from jsonb_array_elements(contenu->'rangs') with ordinality as t(r, o))) where id = 'sv-2';
update public.partenaires set logo = 'm-logo-frb' where id = 'pa-frb';
update public.partenaires set logo = 'm-logo-relais-social' where id = 'pa-relais';
update public.partenaires set logo = 'm-logo-espace-p' where id = 'pa-espacep';
update public.reglages set credit_libelle = 'Ce site a fièrement été réalisé par Nomad Impact, le capacity builder du non-marchand.' where id = 'general';
commit;
select (select count(*) from public.medias where id in ('m-promotion-sante','m-don-nature','m-logo-relais-social','m-logo-espace-p','m-logo-frb')) as medias, (select photo from public.services where slug='promotion-sante') as photo_sante, (select contenu->>'image' from public.sections where id='dn-1') as image_don, (select count(*) from public.partenaires where logo <> '') as logos, (select credit_libelle from public.reglages where id='general') as credit;
